BEGIN;
CREATE TABLE IF NOT EXISTS requisicoes_compra (id INTEGER PRIMARY KEY AUTOINCREMENT,numero TEXT UNIQUE,status TEXT NOT NULL,versao INTEGER NOT NULL DEFAULT 0,tipo_origem TEXT NOT NULL,origem_id INTEGER,origem_numero_snapshot TEXT,origem_descricao_snapshot TEXT NOT NULL,origem_setor_snapshot TEXT,origem_equipamento_snapshot TEXT,origem_dados_snapshot TEXT NOT NULL,setor TEXT NOT NULL,solicitante_id INTEGER,solicitante_nome_snapshot TEXT NOT NULL,responsavel_id INTEGER,responsavel_nome_snapshot TEXT,prioridade TEXT NOT NULL,justificativa TEXT,observacoes TEXT,chave_criacao TEXT NOT NULL UNIQUE,criado_por INTEGER,criado_em TEXT NOT NULL,enviado_por INTEGER,enviado_em TEXT,aprovado_por INTEGER,aprovado_em TEXT,rejeitado_por INTEGER,rejeitado_em TEXT,motivo_rejeicao TEXT,cancelado_por INTEGER,cancelado_em TEXT,motivo_cancelamento TEXT,atualizado_em TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requisicao_compra_itens (id INTEGER PRIMARY KEY AUTOINCREMENT,requisicao_compra_id INTEGER NOT NULL,material_id INTEGER,descricao_snapshot TEXT NOT NULL,unidade_snapshot TEXT NOT NULL,quantidade_solicitada REAL NOT NULL,custo_estimado_unitario REAL,observacao TEXT,status TEXT NOT NULL DEFAULT 'SOLICITADO',pendente_cadastro INTEGER NOT NULL DEFAULT 0,criado_em TEXT NOT NULL,atualizado_em TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requisicao_compra_eventos (id INTEGER PRIMARY KEY AUTOINCREMENT,requisicao_compra_id INTEGER NOT NULL,item_id INTEGER,evento TEXT NOT NULL,status_anterior TEXT,status_novo TEXT,dados_anteriores TEXT,dados_novos TEXT,justificativa TEXT,usuario_id INTEGER,usuario_nome TEXT NOT NULL,perfil TEXT NOT NULL,criado_em TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE);
CREATE INDEX IF NOT EXISTS idx_rc_origem ON requisicoes_compra(tipo_origem,origem_id,status); CREATE INDEX IF NOT EXISTS idx_rc_status_data ON requisicoes_compra(status,criado_em); CREATE INDEX IF NOT EXISTS idx_rc_solicitante ON requisicoes_compra(solicitante_id); CREATE INDEX IF NOT EXISTS idx_rc_item_material ON requisicao_compra_itens(material_id,requisicao_compra_id);
COMMIT;
